[ROOT_MNT, MNT_ANDROID] if androidSdcardMounted() || androidPathMounted("/") => {
    let mut entries = Vec::new();
    if androidSdcardMounted() {
        entries.push(directoryEntry(MNT_ANDROID_SDCARD));
    }
    if androidPathMounted("/") {
        entries.push(directoryEntry("root"));
    }
    Ok(Some(entries))
}

[ROOT_MNT, MNT_ANDROID, "root", rest @ ..] => {
    if !androidPathMounted("/") {
        return Err("/mnt/android/root is not mounted".to_string());
    }
    Ok(ResolvedVfsPath {
        vfsPath: joinNormalizedSegments(&[ROOT_MNT, MNT_ANDROID, "root"], rest),
        physicalPath: physicalPathString(joinUnixPhysical("/", rest)),
    })
}
